@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
}

class Institution {
  + institutionCode : string
}

class Article {
  + DOI : string
  + title : string
}

class PeerReviewedPaper extends Article {
  + citationCount : int
}

class TechnicalReport extends Article {
}

class AuthorPosition {
  + position : int
}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

Person "1" -- "*" Article : authors
Person "1" -- "*" Article : reviews
Person "*" -- "1" Institution : works for

Article "1" -- "*" AuthorPosition : has
Person "1" -- "*" AuthorPosition : in position

TechnicalReport "*" -- "1" Institution : published by
PeerReviewedPaper "*" -- "1" Journal : published in
Journal "*" -- "1" Publisher : published by
Institution "*" -- "*" Journal : subscribes to

@enduml

